def calculate_factorial(n: int) -> int:
    if not isinstance(n, int) or n < 0:
        raise ValueError(f"Input must be a non-negative integer. Received: {n}")

    if n == 0:
        print(f"Calculating factorial for n = {n}. Base case: returning 1.")
        return 1
    else:
        print(f"Calculating factorial for n = {n}.")
        result = 1
        for i in range(1, n + 1):
            result *= i
            print(f"Intermediate step: multiplying by {i}, current result is {result}.")
        print(f"Factorial of {n} is {result}.")
        return result

if __name__ == '__main__':
    test_cases = [0, 1, 5, 7]
    for num in test_cases:
        try:
            factorial_value = calculate_factorial(num)
            print(f"The factorial of {num} is: {factorial_value}\n")
        except ValueError as e:
            print(f"Error for input {num}: {e}\n")

    print(f"Attempting an invalid input: -3")
    try:
        calculate_factorial(-3)
    except ValueError as e:
        print(f"Caught expected error: {e}")

