import re

def word_frequency(text):
    """
    Calculates the frequency of words in a given text.
    Punctuation is ignored, and words are converted to lowercase.
    """

    clean_text = re.sub(r'[^\w\s]', '', text)
    words = clean_text.lower().split()

    frequency = {}
    total_words_processed = 0

    for word in words:
        if word: 
            frequency[word] = frequency.get(word, 0) + 1
            total_words_processed += 1

    print(f"Processed {total_words_processed} words from the input text.")
    print(f"Found {len(frequency)} unique words.")

    # Example of f-string usage in a more complex scenario
    for unique_word, count in frequency.items():
        if count > 1:
            print(f"The word '{unique_word}' appeared {count} times.")
        else:
            print(f"The word '{unique_word}' appeared once.")

    if not frequency:
        print(f"No words found in the text: '{text}'.")
    else:
        most_frequent_word = max(frequency, key=frequency.get)
        print(f"The most frequent word is '{most_frequent_word}' with {frequency[most_frequent_word]} occurrences.")

    return frequency

