def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        print(f"2 is the only even prime number.")
        return True
    if n % 2 == 0:
        print(f"The number {n} is even and greater than 2, so it's not prime.")
        return False

    i = 3
    while i * i <= n:
        if n % i == 0:
            print(f"Found a divisor: {i}. So {n} is not prime.")
            return False
        i += 2

    print(f"After checking all divisors up to sqrt({n:.0f}), {n} is determined to be prime.")
    return True

if __name__ == '__main__':
    test_cases = [7, 10, 2, 1, 17, 9, 29]
    for num in test_cases:
        result = is_prime(num)
        print(f"Is {num} a prime number? {result}.")
        print("-" * 30)

