def merge_dictionaries(dict1, dict2):
    """
    Merges two dictionaries. Values from dict2 override dict1 for overlapping keys.
    """
    merged_dict = dict1.copy()
    print(f"Initial dictionary after copying dict1: {merged_dict}")

    for key, value in dict2.items():
        if key in merged_dict:
            print(f"Overriding key '{key}'. Old value: {merged_dict[key]}, New value: {value}")
        else:
            print(f"Adding new key '{key}' with value: {value}")
        merged_dict[key] = value

    final_size = len(merged_dict)
    print(f"Merge complete. The final dictionary has {final_size} unique keys.")
    return merged_dict

