import math

def geometric_mean(numbers):
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    product = 1.0
    for num in numbers:
        if num <= 0:
            raise ValueError(f"All numbers must be positive. Found: {num}")
        product *= num

    n = len(numbers)

    # Calculate the nth root
    nth_root = product**(1/n)

    # Optional: Format for consistent output if very close to an integer
    if abs(nth_root - round(nth_root)) < 1e-9:
        return float(round(nth_root))

    return nth_root

if __name__ == '__main__':
    test_cases = [
        ([2, 8], 4.0),
        ([1, 1, 1], 1.0),
        ([3, 9, 27], 9.0),
        ([10, 100, 1000], 100.0),
        ([1, 2, 3, 4, 5], 2.605171084697351), # Approximate value
        ([0.5, 2.0], 1.0),
    ]

    for numbers_input, expected_output in test_cases:
        try:
            result = geometric_mean(numbers_input)
            print(f"Geometric mean of {numbers_input} is: {result}. Expected: {expected_output}.")
            assert abs(result - expected_output) < 1e-9, f"Test failed for {numbers_input}. Got {result}, expected {expected_output}"
            print(f"Test passed for input {numbers_input}.")
        except ValueError as e:
            print(f"Caught expected error for input {numbers_input}: {e}")
        except AssertionError as e:
            print(f"Assertion failed: {e}")

    # Test cases for errors
    print("\nTesting error conditions:")
    try:
        geometric_mean([])
    except ValueError as e:
        print(f"Successfully caught expected error for empty list: {e}")

    try:
        geometric_mean([1, -2, 3])
    except ValueError as e:
        print(f"Successfully caught expected error for negative number: {e}")

