    sentences = []
    current_sentence = ""
    for i, char in enumerate(text):
        current_sentence += char
        if char in ['.', '!', '?'] and (i + 1 == len(text) or text[i+1] == ' '):
            sentences.append(current_sentence.strip())
            current_sentence = ""
    if current_sentence:
        sentences.append(current_sentence.strip())

    capitalized_sentences = []
    for j, sentence in enumerate(sentences):
        if sentence:
            first_char = sentence[0].upper()
            rest_of_sentence = sentence[1:]
            capitalized_sentences.append(f"{first_char}{rest_of_sentence}")
        else:
            capitalized_sentences.append("")

    result = ""
