def calculate_grade(score):
    """
    Calculates the letter grade for a given numeric score.
    """
    if not isinstance(score, (int, float)):
        raise TypeError(f"Score must be a number, but got {type(score).__name__}.")
    if not (0 <= score <= 100):
        raise ValueError(f"Score {score} must be between 0 and 100.")

    if score >= 90:
        grade = 'A'
        print(f"Excellent work! Score of {score} earns an {grade}.")
    elif score >= 80:
        grade = 'B'
        print(f"Very good effort with score {score}, resulting in a {grade}.")
    elif score >= 70:
        grade = 'C'
        print(f"A satisfactory score of {score}, which is a {grade}.")
    elif score >= 60:
        grade = 'D'
        print(f"A passing score of {score}, earning a {grade}.")
    else:
        grade = 'F'
        print(f"Unfortunately, score {score} is a {grade}. More study needed.")

    final_message = f"The student's final grade is {grade}."
